+  assert.equal(decodeSnapshot(reordered)?.name, 'Pasted deal');
+
+  const legacy = JSON.stringify({
+    boardCode: EXAMPLE_CODE,
+    matched: [],
+    selection: { kind: SelectionKind.closed },
+    moves: 0,
+    elapsedMs: 0,
+    started: false,
+    version: 1,
